python3 - <<'PY'
p='engine-tests/install.test.mjs'
s=open(p).read()
old = """  // The paths moved with the flows (#1317). The old `updates/*` re-exports were deleted
  // once the fleet's workers had been read and none named them — which is what chain link
  // L3 confirms; a worker one cycle behind loads these from the canon tree it just fetched.
  const fielded = {
    'packs/claudinite-lifecycle/updates/terminals.mjs': ['terminalFor'],
    'packs/claudinite-lifecycle/updates/engine-update.mjs': ['engineUpdate'],
    'packs/claudinite-lifecycle/updates/pack-update.mjs': ['packUpdate'],
  };"""
new = """  // The paths moved with the flows (#1317), and BOTH are fielded right now. The worker
  // resolves these against a fresh canon clone at HEAD rather than its own mount, so the
  // surface a member calls is whatever ITS vendored worker names — and every member
  // vendored a worker naming `updates/*` on 2026-08-24. The pack paths are what the
  // worker names from this commit on; the `updates/*` re-exports stay callable until the
  // fleet has vendored that worker, read off the members, never off this repo's tree.
  const fielded = {
    'updates/terminals.mjs': ['terminalFor'],
    'updates/engine-update.mjs': ['engineUpdate'],
    'updates/pack-update.mjs': ['packUpdate'],
    'packs/claudinite-lifecycle/updates/terminals.mjs': ['terminalFor'],
    'packs/claudinite-lifecycle/updates/engine-update.mjs': ['engineUpdate'],
    'packs/claudinite-lifecycle/updates/pack-update.mjs': ['packUpdate'],
  };"""
assert s.count(old)==1
open(p,'w').write(s.replace(old,new))
print('patched')
